// Alert sounds + haptics (redesign spec §8). Shared verbatim by apps/customer
// and apps/pro; assets/sounds/*.wav are duplicated per app because Metro
// resolves `require` relative to each app. The wavs are generated by
// mobile/tools/generate-sounds.mjs.
//
// Every call is guarded — a missing/unavailable audio device must never be
// able to crash a status update or a bid submission.
//
// Respecting silent/DND: short UI cues use the media player at the user's own
// media volume (never overriding it, and never playing through the iOS silent
// switch). The repeating new-job ring is delivered as a local notification on
// the high-importance "new-job-alert" channel, so Android's own ringer/DND
// rules apply to it; when the phone is silenced only the repeating haptic
// pattern remains.
import { Platform, Vibration } from "react-native";
import * as Notifications from "expo-notifications";
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from "expo-audio";
import * as Haptics from "expo-haptics";
import { CHANNELS } from "./notifications";

let modeConfigured = false;
async function ensureAudioMode() {
  if (modeConfigured) return;
  modeConfigured = true;
  try {
    // playsInSilentMode:false → honour the iOS silent switch.
    await setAudioModeAsync({ playsInSilentMode: false });
  } catch {}
}

type SoundName = "new_job_alert" | "bid_accepted" | "message_received" | "job_status_update" | "job_done" | "payment_added";

// Metro needs static require() calls.
const SOURCES: Record<SoundName, number> = {
  new_job_alert: require("../../assets/sounds/new_job_alert.wav"),
  bid_accepted: require("../../assets/sounds/bid_accepted.wav"),
  message_received: require("../../assets/sounds/message_received.wav"),
  job_status_update: require("../../assets/sounds/job_status_update.wav"),
  job_done: require("../../assets/sounds/job_done.wav"),
  payment_added: require("../../assets/sounds/payment_added.wav"),
};

// Distinct haptic per sound, for when the phone is on silent.
const PATTERNS: Record<Exclude<SoundName, "new_job_alert">, number[]> = {
  bid_accepted: [0, 80, 60, 80, 60, 160],
  payment_added: [0, 50, 40, 90],
  job_done: [0, 70, 50, 70, 50, 200],
  message_received: [0, 40],
  job_status_update: [0, 60],
};
// One pulse train repeating until stopped: buzz-buzz-buzz … pause.
const RING_PATTERN = [0, 500, 250, 500, 250, 500, 900];

const players: Partial<Record<SoundName, AudioPlayer>> = {};
function getPlayer(name: SoundName): AudioPlayer | null {
  try {
    return (players[name] ??= createAudioPlayer(SOURCES[name]));
  } catch (e) {
    console.warn("[sound] failed to load player", name, e);
    return null;
  }
}

async function playOnce(name: Exclude<SoundName, "new_job_alert">) {
  try {
    Vibration.vibrate(PATTERNS[name]);
    if (Platform.OS === "ios") Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
  } catch {}
  try {
    await ensureAudioMode();
    const player = getPlayer(name);
    if (!player) return;
    player.seekTo(0);
    player.play();
  } catch (e) {
    console.warn("[sound] play failed", name, e);
  }
}

// ─── New-job ring ───
// new_job_alert.wav is a 5.6 s file; the offer window is ~15 s (2–3 loops),
// matching ride-hailing dispatch timing — a longer ring slows dispatch for
// the customer without helping the Pro notice any better.
export const RING_LOOP_MS = 5600;
export const RING_WINDOW_MS = 15000;
const RING_NOTIFICATION_ID = "servigic-job-ring";

let ringTimers: ReturnType<typeof setTimeout>[] = [];
let ringActive = false;

async function fireRingOnce(job?: { title: string; body: string }) {
  try {
    const { granted } = await Notifications.getPermissionsAsync();
    if (granted) {
      await Notifications.scheduleNotificationAsync({
        identifier: RING_NOTIFICATION_ID,
        content: {
          title: job?.title ?? "New job nearby",
          body: job?.body ?? "Open Servigic Pro to view and bid.",
          sound: "new_job_alert.wav",
          priority: Notifications.AndroidNotificationPriority.MAX,
        },
        trigger: { channelId: CHANNELS.newJob },
      });
      return;
    }
  } catch (e) {
    console.warn("[sound] ring notification failed, falling back to player", e);
  }
  // Notifications not permitted: fall back to the in-app player.
  try {
    await ensureAudioMode();
    const player = getPlayer("new_job_alert");
    player?.seekTo(0);
    player?.play();
  } catch {}
}

export const sound = {
  // Bid submitted successfully.
  bidSent: () => playOnce("job_status_update"),
  // Booking status changed (on the way / arrived / working / confirmed).
  statusChanged: () => playOnce("job_status_update"),
  bidAccepted: () => playOnce("bid_accepted"),
  jobDone: () => playOnce("job_done"),
  paymentAdded: () => playOnce("payment_added"),
  messageReceived: () => playOnce("message_received"),

  // Starts the repeating job ring; auto-stops after RING_WINDOW_MS and calls
  // onTimeout. Any Accept/Decline/tap must call sound.stopRing() immediately.
  startRing: (job?: { title: string; body: string }, onTimeout?: () => void) => {
    sound.stopRing();
    ringActive = true;
    try {
      Vibration.vibrate(RING_PATTERN, true);
    } catch {}
    fireRingOnce(job);
    for (let at = RING_LOOP_MS; at < RING_WINDOW_MS; at += RING_LOOP_MS) {
      ringTimers.push(setTimeout(() => ringActive && fireRingOnce(job), at));
    }
    ringTimers.push(
      setTimeout(() => {
        if (!ringActive) return;
        sound.stopRing();
        onTimeout?.();
      }, RING_WINDOW_MS)
    );
  },
  stopRing: () => {
    ringActive = false;
    ringTimers.forEach(clearTimeout);
    ringTimers = [];
    try {
      Vibration.cancel();
    } catch {}
    try {
      players.new_job_alert?.pause();
    } catch {}
    Notifications.dismissNotificationAsync(RING_NOTIFICATION_ID).catch(() => {});
    Notifications.cancelScheduledNotificationAsync(RING_NOTIFICATION_ID).catch(() => {});
  },
};
